// math.js
export const PI = 3.14159;  // экспортируем константу

export function add(a, b) {
  return a + b;  // экспортируем функцию
}

// app.js
import { PI, add } from './math.js';
console.log(PI);      // 3.14159
console.log(add(2, 3));  // 5

// Без модулей: конфликт!
// lib1.js: const utils = { format: ... }
// lib2.js: const utils = { parse: ... }  // перезаписал! БАГ!

// С модулями: изоляция
// lib1.js
export const utils = { format() { /*...*/ } };

// lib2.js
export const utils = { parse() { /*...*/ } };

// app.js — импортируем под разными именами
import { utils as fmt } from './lib1.js';
import { utils as parse } from './lib2.js';
// Никакого конфликта!

// utils.js — несколько named exports
export const name = "Alice";
export const age = 25;

export function greet() {
  return `Hi, ${name}`;
}

// app.js — импортируем по именам
import { name, greet } from './utils.js';
console.log(name);     // Alice
console.log(greet());   // Hi, Alice

// Можно импортировать всё звёздочкой:
import * as utils from './utils.js';
console.log(utils.name);  // Alice

// user.js — default export
class User {
  constructor(name) { this.name = name; }
}
export default User;  // главный экспорт файла

// app.js — импорт default (имя выбираешь сам)
import Person from './user.js';  // Person = User
const p = new Person("Alice");
console.log(p.name);  // Alice

// Важно: default импортируется БЕЗ фигурных скобок!

